import sys, json, yaml
pack, hs = sys.argv[1], json.load(open(sys.argv[2]))
structs = yaml.safe_load(open(f"{pack}/structures.yaml", encoding="utf-8"))
out = ["# Hotspot anchors for <model-viewer> (model space, metres, glTF +Y up / +Z front).",
       "# Generated by content/_tools/hotspots.py from build_glb.py output: front-most surface point at each node's mid-height.",
       "# Use as data-position / data-normal on hotspot buttons."]
for s in structs:
    h = hs.get(s["mesh_name"] or "")
    if not h: continue
    p, n = h["position"], h["normal"]
    out += [f"- structure_id: {s['id']}", f"  mesh_name: {s['mesh_name']}",
            f"  position: \"{p[0]}m {p[1]}m {p[2]}m\"", f"  normal: \"{n[0]} {n[1]} {n[2]}\""]
open(f"{pack}/hotspots.yaml", "w", encoding="utf-8").write("\n".join(out) + "\n")
